#!/usr/bin/env bash
# Phase 2 gate (SPEC §8): fmt, clippy -D warnings, cargo test (unit + Xvfb + nested-KWin shape +
# nested-KWin GUI), typecheck + UI build, npm audit clean, bindings regenerated byte-identical and
# checked, byte-identical legacy renderer copies, no duplicate gtk/specta/zbus, and proof that the
# live island, the legacy source trees and the real session were left alone.
# Usage: island-tauri/scripts/phase2-gate.sh   (CLEAN=1 for a from-scratch cargo build)
# Earlier gates are separate; Phase 1.5 has only the authorized SPEC §8 nullable-grep amendment.
set -euo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
REPO="$(cd "$ROOT/.." && pwd)"
LIVE_EXE="$REPO/island-rust/target/release/hermes-island"
export PATH="$HOME/.cargo/bin:$PATH"
cd "$ROOT"
EVID="$ROOT/evidence/phase2"
mkdir -p "$EVID"

live_pids() { local p; for p in $(pgrep -x hermes-island || true); do
  [[ "$(readlink "/proc/$p/exe" 2>/dev/null || true)" == "$LIVE_EXE" ]] && echo "$p"; done; }
live_stamp() { for p in $(live_pids); do echo "$p start=$(ps -o lstart= -p "$p")"; done; }
tauri_procs() { local p; for p in $(pgrep -x hermes-island || true); do
  [[ "$(readlink "/proc/$p/exe" 2>/dev/null || true)" == "$ROOT/src-tauri/target/"* ]] && echo "$p"; done; }
audit() {
  echo "x11-sockets: $(ls /tmp/.X11-unix | tr '\n' ' ')"
  echo "runtime-dir hits: $(ls "${XDG_RUNTIME_DIR:-/run/user/$(id -u)}" 2>/dev/null | grep -E 'hi-kw|hermes-island|kwin-xwayland-eis' | tr '\n' ' ')"
  echo "scratch-dirs: $(ls -d "${TMPDIR:-/tmp}"/hi-kwin-* "${TMPDIR:-/tmp}"/hi-xvfb-* "${TMPDIR:-/tmp}"/hi-gui-* 2>/dev/null | tr '\n' ' ')"
  echo "real-home: $(ls -d "$HOME/.local/share/local.hermes.island" "$HOME/.config/xfce4" 2>/dev/null | tr '\n' ' ')"
  echo "autostart: $(sha256sum "$HOME/.config/autostart/hermes-island.desktop" 2>/dev/null | cut -d' ' -f1)"
  echo "leaked-procs: $(pgrep -af 'kwin_wayland --virtual|hi-kw-|eis_pointer.py|eis_input.py|Xvfb -screen' | grep -v pgrep | tr '\n' ';')"
  echo "tauri-island-procs: $(tauri_procs | tr '\n' ' ')"
}
# legacy source trees the gate must not change (content hash of every tracked-or-untracked file)
legacy_hash() { (cd "$REPO" && find island island-rust/src island-rust/Cargo.toml island-native/src src \
    -type f -not -path '*/node_modules/*' -not -path '*/dist/*' -not -path '*/__pycache__/*' -not -path '*/evidence/*' \
    -print0 | sort -z | xargs -0 sha256sum | sha256sum | cut -d' ' -f1; sha256sum package.json | cut -d' ' -f1); }

BEFORE_LIVE="$(live_stamp)"; BEFORE_AUDIT="$(audit)"; BEFORE_LEGACY="$(legacy_hash)"
echo "== live island before: $(echo "$BEFORE_LIVE" | tr '\n' ';')"
echo "== audit before"; echo "$BEFORE_AUDIT"
# Controller amendment (Oct 31, Phase 6b2 audit): live island is only a leak detector; not running before is fine (after must still equal before).
if [[ -z "$BEFORE_LIVE" ]]; then echo "NOTE: live island not running before (after must stay not running)"; fi
[[ -z "$(tauri_procs)" ]] || { echo "FAIL: a Tauri island process is already running"; exit 1; }

if [[ "${CLEAN:-0}" == 1 ]]; then echo "== clean build"; rm -rf dist src-tauri/target; fi
rm -f "$EVID"/*.png

echo "== legacy renderer copies are byte-identical to island/ (SPEC §6)"
# renderer.jsx alone carries the pinned Phase 3 ownership amendment (SPEC §8 Phase 3): the live
# diff must equal ui/legacy/renderer.ownership.patch byte-for-byte.
# (`diff` exits 1 when the files differ, which is expected here; only `cmp` decides.)
if ! (diff -u --label island/renderer.jsx --label island-tauri/ui/legacy/renderer.jsx "$REPO/island/renderer.jsx" ui/legacy/renderer.jsx || true) \
    | cmp - ui/legacy/renderer.ownership.patch; then echo "FAIL: renderer.jsx drifted from island/renderer.jsx + renderer.ownership.patch"; exit 1; fi
echo "renderer.jsx == island/renderer.jsx + renderer.ownership.patch"
for f in monitor.jsx ai-stats.jsx state.cjs palette.cjs click-sound.cjs style.css; do
  cmp "$REPO/island/$f" "ui/legacy/$f" && echo "same $f"
done
for f in OpenRunde-Regular OpenRunde-Medium OpenRunde-Semibold OpenRunde-Bold; do
  cmp "$REPO/src/assets/fonts/$f.woff" "ui/src/assets/fonts/$f.woff" && echo "same $f.woff"
done

echo "== npm audit (must be clean, including dev dependencies)"
npm audit 2>&1 | tee "$EVID/npm-audit.txt"
npm audit --omit=dev >/dev/null
echo "== npm run typecheck"; npm run typecheck
echo "== node parse-ack and shim unit tests"; node --test scripts/*.test.mjs
echo "== npm run build:ui"; npm run build:ui
test -f dist/legacy.html -a -f dist/index.html

cd src-tauri
echo "== bindings: regenerate, must equal the checked-in file, then checked"
BEFORE_SHA="$(sha256sum ../ui/ipc/bindings.ts | cut -d' ' -f1)"
cargo test --locked --lib export_bindings -- --ignored 2>&1 | grep -E '^test |test result'
AFTER_SHA="$(sha256sum ../ui/ipc/bindings.ts | cut -d' ' -f1)"
echo "bindings sha256 before=$BEFORE_SHA after=$AFTER_SHA"
[[ "$BEFORE_SHA" == "$AFTER_SHA" ]] || { echo "FAIL: checked-in bindings were stale (now regenerated; re-run)"; exit 1; }
if grep -nE '_Serialize|_Deserialize|bigint' ../ui/ipc/bindings.ts; then echo "FAIL: split/bigint types in bindings"; exit 1; fi
(cd .. && node scripts/check-bindings.mjs)
(cd .. && npm run typecheck >/dev/null && echo "typecheck against regenerated bindings: ok")

echo "== cargo fmt --check";  cargo fmt --check
echo "== cargo clippy --all-targets --locked -- -D warnings"; cargo clippy --all-targets --locked -- -D warnings
echo "== cargo test --locked (lib + xvfb_shape + kwin_shape + kwin_gui)"
cargo test --locked 2>&1 | grep -E '^test |test result|Running|panicked|FAILED' | tee "$EVID/cargo-test.txt"
! grep -q FAILED "$EVID/cargo-test.txt"
grep -q 'kwin_gui' "$EVID/cargo-test.txt" || { echo "FAIL: kwin_gui did not run"; exit 1; }

echo "== dependency decisions"
echo "-- cargo tree -i gtk";    cargo tree --locked -i gtk | head -4
echo "-- cargo tree -i specta"; cargo tree --locked -i specta | head -3
DUPS="$(cargo tree --locked -d | grep -E '^(gtk|gdk|glib|cairo-rs|specta|tauri|wry|tao|zbus) ' || true)"
[[ -z "$DUPS" ]] && echo "(no duplicate gtk/gdk/glib/cairo-rs/specta/tauri/wry/tao/zbus)" || { echo "FAIL duplicates: $DUPS"; exit 1; }
if cargo tree --locked -i keyring >/dev/null 2>&1; then echo "FAIL: keyring is in the dependency tree"; exit 1; else echo "keyring: absent"; fi

cd "$ROOT"
AFTER_LIVE="$(live_stamp)"; AFTER_AUDIT="$(audit)"; AFTER_LEGACY="$(legacy_hash)"
echo "== live island after: $(echo "$AFTER_LIVE" | tr '\n' ';')"
echo "== audit after"; echo "$AFTER_AUDIT"
[[ "$BEFORE_LIVE" == "$AFTER_LIVE" ]] || { echo "FAIL: live island changed"; exit 1; }
[[ "$BEFORE_AUDIT" == "$AFTER_AUDIT" ]] || { echo "FAIL: audit changed:"; diff <(echo "$BEFORE_AUDIT") <(echo "$AFTER_AUDIT") || true; exit 1; }
[[ "$BEFORE_LEGACY" == "$AFTER_LEGACY" ]] || { echo "FAIL: legacy trees or root package.json changed"; exit 1; }
echo "legacy trees + root package.json unchanged ($(echo "$AFTER_LEGACY" | head -1 | cut -c1-16)…)"
echo "PASS: Phase 2 gate (live island PID/start unchanged, no leaks)"
